def get_raw_verse(abbrev, ch, v):
    if abbrev not in books_map:
        return None
    b = books_map[abbrev]
    if ch - 1 < 0 or ch - 1 >= len(b['chapters']):
        return None
    chapter = b['chapters'][ch - 1]
    if v - 1 < 0 or v - 1 >= len(chapter):
        return None
    return chapter[v - 1].strip()

